//! # 2025 day 9 - Movie Theater
//!
//! ## Part 1
//!
//! The input is stored in a list of all possible rectangles that can be created with two points,
//! and sorted by their area. The largest possible area can then be retrieved from the last element
//! in the list.
//!
//! ## Part 2
//!
//! Sort of a brute force solution.
//! Along with the sorted list of rectangles, a list of lines generated by two consecutive points
//! in the input is also created. Then each rectangle is validated by checking if there are any
//! line that intersects its borders. This requires iterating through every single line to validate
//! a single rectangle, but by iterating over the sorted rectangle list we can stop once we find a
//! valid rectangle, since that will then be the largest possible, greatly reducing the number of
//! rectangles that needs to be processed.
//!
//! Not a slow solution by any means, but I might want to look into "sweep line algorithm" in the
//! future for possible improvements.
use crate::aoc_util::{
    error::{AocError, OptionExt},
    point::Point,
};
use std::str::FromStr;

pub fn solve(input: &str) -> Result<(String, String), AocError> {
    let solution_data: InputData = input.parse()?;
    Ok((
        solution_data.solve_part1().to_string(),
        solution_data.solve_part2()?.to_string(),
    ))
}

#[derive(PartialEq, Eq, PartialOrd, Ord)]
struct Rectangle {
    area: u64,
    upper_left: Point,
    lower_right: Point,
}

impl Rectangle {
    fn new(p1: &Point, p2: &Point) -> Self {
        let width = u64::from(p1.x.abs_diff(p2.x)) + 1;
        let height = u64::from(p1.y.abs_diff(p2.y)) + 1;
        Self {
            area: width * height,
            upper_left: Point::new(p1.x.min(p2.x), p1.y.min(p2.y)),
            lower_right: Point::new(p1.x.max(p2.x), p1.y.max(p2.y)),
        }
    }
}

struct Line {
    base_point: Point,
    end: i32,
    is_horizontal: bool,
}

impl Line {
    fn new(p1: &Point, p2: &Point) -> Result<Self, AocError> {
        if p1.x == p2.x {
            Ok(Self {
                base_point: Point::new(p1.x, p1.y.min(p2.y)),
                end: p1.y.max(p2.y),
                is_horizontal: false,
            })
        } else if p1.y == p2.y {
            Ok(Self {
                base_point: Point::new(p1.x.min(p2.x), p1.y),
                end: p1.x.max(p2.x),
                is_horizontal: true,
            })
        } else {
            Err(AocError::Invalid(format!(
                "can't make line from: {p1} - {p2}"
            )))
        }
    }

    fn intersects_rectangle(&self, r: &Rectangle) -> bool {
        // Note: this will also consider a line completely inside the rectangle as intersecting. Since all lines are contiguous,
        // then if one individual line is inside then another line WILL intersect somewhere, so we might as well invalidate
        // the rectangle already now.
        if self.is_horizontal {
            r.upper_left.y < self.base_point.y
                && self.base_point.y < r.lower_right.y
                && self.base_point.x < r.lower_right.x
                && self.end > r.upper_left.x
        } else {
            r.upper_left.x < self.base_point.x
                && self.base_point.x < r.lower_right.x
                && self.base_point.y < r.lower_right.y
                && self.end > r.upper_left.y
        }
    }
}

struct InputData {
    rectangles: Vec<Rectangle>,
    lines: Vec<Line>,
    max_area: u64,
}

impl FromStr for InputData {
    type Err = AocError;
    fn from_str(s: &str) -> Result<Self, Self::Err> {
        let red_tiles: Vec<_> = s
            .lines()
            .map(|line| line.parse())
            .collect::<Result<_, _>>()?;
        if red_tiles.len() < 3 {
            return Err(AocError::Invalid("not enough points".to_string()));
        }
        let mut rectangles = Vec::new();
        for i in 0..red_tiles.len() - 2 {
            // Note: skip the first following entry, since that will effectively only make a line rather than a rectangle
            for j in i + 2..red_tiles.len() {
                rectangles.push(Rectangle::new(&red_tiles[i], &red_tiles[j]));
            }
        }
        rectangles.sort_unstable();
        let max_area = rectangles.last().ctx("no rectangles")?.area;
        let mut lines: Vec<_> = red_tiles
            .windows(2)
            .map(|p| Line::new(&p[0], &p[1]))
            .collect::<Result<_, _>>()?;
        lines.push(Line::new(
            red_tiles.last().ctx("not enough points")?,
            red_tiles.first().ctx("not enough points")?,
        )?);
        Ok(Self {
            rectangles,
            lines,
            max_area,
        })
    }
}

impl InputData {
    fn is_rectangle_valid(&self, r: &Rectangle) -> bool {
        !self.lines.iter().any(|line| line.intersects_rectangle(r))
    }

    fn solve_part1(&self) -> u64 {
        self.max_area
    }

    fn solve_part2(&self) -> Result<u64, AocError> {
        for rectangle in self.rectangles.iter().rev() {
            if self.is_rectangle_valid(rectangle) {
                return Ok(rectangle.area);
            }
        }
        Err(AocError::NoSolution)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    const TEST_OFFICIAL_1: &str = "7,1
11,1
11,7
9,7
9,5
2,5
2,3
7,3";

    #[test]
    fn part1_official_1() {
        let solution_data: InputData = TEST_OFFICIAL_1.parse().unwrap();
        assert_eq!(solution_data.solve_part1(), 50);
    }

    #[test]
    fn part2_official_1() {
        let solution_data: InputData = TEST_OFFICIAL_1.parse().unwrap();
        assert_eq!(solution_data.solve_part2().unwrap(), 24);
    }

    #[test]
    fn parser_invalid_input() {
        for input in [
            "0,0\n1,1\n2,1", // diagonal consecutive points
            "0,0\n1,1",      // too few points
        ] {
            assert!(matches!(
                input.parse::<InputData>(),
                Err(AocError::Invalid(_))
            ));
        }
    }

    #[test]
    fn part2_no_solution() {
        let data = InputData {
            rectangles: vec![Rectangle::new(&Point::new(0, 0), &Point::new(2, 2))],
            lines: vec![Line::new(&Point::new(0, 1), &Point::new(2, 1)).unwrap()],
            max_area: 9,
        };
        assert_eq!(data.solve_part2(), Err(AocError::NoSolution));
    }
}
